## Patch sketch

```js
const crypto = require('crypto');

const TOLERANCE_SEC = 300; // 5 minutes

class WebhookVerificationError extends Error {
  constructor(msg) { super(msg); this.name = 'WebhookVerificationError'; }
}

function parseSignatureHeader(header) {
  // Expected: "t=<unix>,v1=<hex>"
  if (typeof header !== 'string') {
    throw new WebhookVerificationError('signature header is not a string');
  }

  const parts = {};
  for (const segment of header.split(',')) {
    const idx = segment.indexOf('=');
    if (idx === -1) throw new WebhookVerificationError('malformed signature segment');
    parts[segment.slice(0, idx).trim()] = segment.slice(idx + 1).trim();
  }

  if (!parts.t || !parts.v1) {
    throw new WebhookVerificationError('missing t or v1 in signature header');
  }

  const timestamp = Number(parts.t);
  if (!Number.isFinite(timestamp) || timestamp <= 0) {
    throw new WebhookVerificationError('invalid timestamp');
  }

  // Validate hex: only lowercase hex chars, even length, 64 chars for sha256
  if (!/^[0-9a-f]{64}$/.test(parts.v1)) {
    throw new WebhookVerificationError('v1 is not valid sha256 hex');
  }

  return { timestamp, signatureHex: parts.v1 };
}

function verify(signatureHeader, body, secret) {
  const { timestamp, signatureHex } = parseSignatureHeader(signatureHeader);

  // --- Replay protection ---
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - timestamp) > TOLERANCE_SEC) {
    throw new WebhookVerificationError('timestamp outside tolerance window');
  }

  // --- Compute expected HMAC over "t.body" to bind timestamp ---
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${body}`)
    .digest('hex');

  // --- Constant-time comparison ---
  const sigBuf = Buffer.from(signatureHex, 'hex');
  const expBuf = Buffer.from(expected, 'hex');

  if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
    throw new WebhookVerificationError('signature mismatch');
  }

  return true;
}
```

Key changes:

- **Timestamp binding**: HMAC is computed over `"<timestamp>.<body>"` so the signature is tied to the timestamp the sender claims. The receiver rejects if the timestamp drifts beyond ±5 min.
- **Constant-time compare**: Uses `crypto.timingSafeEqual` on fixed-length Buffers (32 bytes each) — no timing leak.
- **Malformed hex**: The regex `/^[0-9a-f]{64}$/` rejects non-hex, odd-length, or wrong-length input before it ever reaches the comparison.
- **Structured errors**: Every failure path throws a typed error with a safe message (no secret material).

