## Three regression tests

```js
const assert = require('assert');

const SECRET = 'test-secret';
const BODY = '{"event":"ping"}';

function makeHeader(timestampOverride) {
  const t = timestampOverride ?? Math.floor(Date.now() / 1000);
  const sig = crypto.createHmac('sha256', SECRET).update(`${t}.${BODY}`).digest('hex');
  return { header: `t=${t},v1=${sig}`, t };
}

// 1. Rejects replayed (stale) timestamp
(function testReplayRejection() {
  const staleT = Math.floor(Date.now() / 1000) - 301; // 5 min + 1 s ago
  const { header } = makeHeader(staleT);
  assert.throws(
    () => verify(header, BODY, SECRET),
    /timestamp outside tolerance/
  );
  console.log('PASS: replay rejection');
})();

// 2. Rejects malformed / non-hex v1
(function testMalformedHex() {
  const t = Math.floor(Date.now() / 1000);
  const bad = `t=${t},v1=ZZZZ`;
  assert.throws(
    () => verify(bad, BODY, SECRET),
    /not valid sha256 hex/
  );
  console.log('PASS: malformed hex rejection');
})();

// 3. Accepts a valid, fresh signature
(function testValidSignature() {
  const { header } = makeHeader();
  assert.strictEqual(verify(header, BODY, SECRET), true);
  console.log('PASS: valid signature accepted');
})();
