PATCH SKETCH

```js
const crypto = require('crypto');

const MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes

function verify(sigHeader, body, secret) {
  // 1. Parse header: "t=<unix>,v1=<hex>"
  if (typeof sigHeader !== 'string') return false;

  const parts = Object.fromEntries(
    sigHeader.split(',').map(p => p.split('=').map(s => s.trim()))
  );

  const ts = parseInt(parts.t, 10);
  const v1 = parts.v1;

  // 2. Reject missing or non-numeric timestamp
  if (!Number.isFinite(ts) || !v1) return false;

  // 3. Reject timestamps older than 5 minutes (or suspiciously future)
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - ts) > MAX_AGE_MS / 1000) return false;

  // 4. Build signed payload: "<t>.<body>"
  const payload = `${ts}.${body}`;
  const expected = crypto
    .createHmac('sha256', secret)
    .update(payload)
    .digest('hex');

  // 5. Safely decode v1 — reject malformed hex before comparison
  if (!/^[0-9a-f]{64}$/i.test(v1)) return false;

  // 6. Constant-time comparison
  const a = Buffer.from(expected, 'hex');
  const b = Buffer.from(v1, 'hex');
  // timingSafeEqual throws if lengths differ; guard above ensures both are 32 bytes
  return crypto.timingSafeEqual(a, b);
}
```

Key changes from original:
- Timestamp is included in the signed payload (t + body), binding the signature to the time value so an attacker cannot swap a fresh timestamp onto an old signature.
- `timingSafeEqual` replaces `===`, eliminating early-exit timing leak.
- Hex regex guard before `timingSafeEqual` prevents length-mismatch throws and rejects garbage inputs without leaking processing time differences.
- Replay window enforced via `Math.abs` to also reject far-future timestamps (clock-skew attack).

