**Translator: Claude Code `Bash` Tool Call Normalizer**

```typescript
// Core translator — minimal, typed, side-effect-free
interface UpstreamBash { cmd?: string; command?: string; [k: string]: unknown }
interface ClientBash   { command: string }

type TranslateResult =
  | { ok: true;  call: ClientBash }
  | { ok: false; reason: 'empty_input' | 'missing_command' | 'wrong_type' }

function translateBash(raw: unknown): TranslateResult {
  if (raw == null || (typeof raw === 'object' && Object.keys(raw).length === 0))
    return { ok: false, reason: 'empty_input' };

  const inp = raw as UpstreamBash;
  const cmd = inp.command ?? inp.cmd;          // alias coercion: cmd → command

  if (cmd === undefined || cmd === null)
    return { ok: false, reason: 'missing_command' };
  if (typeof cmd !== 'string')
    return { ok: false, reason: 'wrong_type' };

  return { ok: true, call: { command: cmd } };
}
```

```typescript
// Routing + cooldown integration
const COOLDOWN_WINDOW_MS = 60_000;
const REROUTE_THRESHOLD  = 3;           // failures within window → reroute

const failureLog: number[] = [];        // timestamps of invalid calls

function handleToolCall(raw: unknown, router: Router): ClientBash | null {
  const result = translateBash(raw);
  if (!result.ok) {
    const now = Date.now();
    failureLog.push(now);
    // Evict entries outside cooldown window
    while (failureLog.length && failureLog[0] < now - COOLDOWN_WINDOW_MS)
      failureLog.shift();

    if (failureLog.length >= REROUTE_THRESHOLD)
      router.reroute({ reason: result.reason, cooldownUntil: now + COOLDOWN_WINDOW_MS });

    return null;   // drop invalid call; caller emits tool_result error to upstream
  }
  return result.call;
}
```

